import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [ticker, setTicker] = useState("RELIANCE.NS");
  const [loading, setLoading] = useState(false);

  const analyzeStock = () => {
    setLoading(true);
    // Backend API kooda connect pannudhu
    axios.get(`http://localhost:8000/api/analyze?tickers=${ticker}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  };

  // First time load aagumbothu automatic-ah Reliance-a analyze pannum
  useEffect(() => {
    analyzeStock();
  }, []);

  return (
    <div style={{ backgroundColor: '#0e1117', color: '#c9d1d9', minHeight: '100vh', padding: '20px', fontFamily: 'Segoe UI, Roboto, sans-serif' }}>
      
      {/* Header Section */}
      <div style={{ borderBottom: '1px solid #30363d', paddingBottom: '20px', marginBottom: '20px' }}>
        <h1 style={{ color: '#58a6ff', margin: 0 }}>🛡️ QuantShield AI Dash</h1>
        <p style={{ fontSize: '14px', color: '#8b949e' }}>Intelligent Portfolio Optimizer & Risk Engine</p>
      </div>

      {/* Search Bar Section */}
      <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', marginBottom: '30px' }}>
        <label style={{ marginRight: '15px', fontWeight: 'bold' }}>🔍 Enter Stock Symbol:</label>
        <input 
          type="text" 
          value={ticker} 
          placeholder="e.g. TCS.NS, INFY.NS"
          onChange={(e) => setTicker(e.target.value.toUpperCase())}
          style={{ 
            background: '#0d1117', color: 'white', border: '1px solid #30363d', 
            padding: '10px', borderRadius: '5px', width: '200px', outline: 'none' 
          }}
        />
        <button 
          onClick={analyzeStock} 
          style={{ 
            background: '#238636', color: 'white', border: 'none', 
            padding: '10px 25px', borderRadius: '5px', marginLeft: '15px', 
            cursor: 'pointer', fontWeight: 'bold' 
          }}
        >
          {loading ? 'Analyzing...' : 'RUN ANALYSIS'}
        </button>
      </div>

      {data && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '20px' }}>
          
          {/* Left Panel: Market Metrics (Screenshot Style) */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#f85149', borderBottom: '1px solid #30363d', paddingBottom: '10px' }}>📊 Market Analysis</h3>
            <div style={{ lineHeight: '2.5', fontSize: '18px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}><span>Sharpe Ratio:</span> <b style={{color: '#58a6ff'}}>{data.sharpe_ratio || data.cps_score}</b></div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}><span>Volatility:</span> <b style={{color: '#f85149'}}>{data.volatility || '0.24'}</b></div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}><span>Market Regime:</span> <b>{data.regime}</b></div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}><span>BSI Score:</span> <b style={{color: '#d2a8ff'}}>{data.bsi_score}</b></div>
            </div>

            {/* Ghost Hedge Status */}
            <div style={{ 
              marginTop: '30px', padding: '15px', borderRadius: '5px',
              background: data.regime === "STRESS" ? '#4a151b' : '#0d1117',
              border: data.regime === "STRESS" ? '1px solid #f85149' : '1px solid #30363d',
              textAlign: 'center'
            }}>
              🛡️ <b>GHOST HEDGE:</b> {data.regime === "STRESS" ? "ACTIVE" : "MONITORING"}
            </div>
          </div>

          {/* Right Panel: Forecasting (Flowchart Logic) */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#58a6ff', borderBottom: '1px solid #30363d', paddingBottom: '10px' }}>🎲 Monte Carlo Forecast (₹10,000)</h3>
            <div style={{ marginTop: '20px' }}>
              <div style={{ background: 'linear-gradient(135deg, #1e293b, #0f172a)', padding: '20px', borderRadius: '10px', marginBottom: '20px', borderLeft: '5px solid #238636' }}>
                <p style={{ margin: 0, color: '#8b949e' }}>Expected Portfolio Value</p>
                <h1 style={{ color: '#3fb950', margin: '10px 0' }}>₹{data.forecast.expected}</h1>
              </div>
              <div style={{ background: 'linear-gradient(135deg, #1e293b, #0f172a)', padding: '20px', borderRadius: '10px', borderLeft: '5px solid #f85149' }}>
                <p style={{ margin: 0, color: '#8b949e' }}>Worst Case Scenario (Risk)</p>
                <h1 style={{ color: '#f85149', margin: '10px 0' }}>₹{data.forecast.worst_case}</h1>
              </div>
            </div>

            {/* AI Verdict */}
            <div style={{ 
              marginTop: '30px', padding: '20px', textAlign: 'center', 
              borderRadius: '10px', background: data.decision === "BUY" ? '#238636' : '#f85149',
              fontSize: '24px', fontWeight: 'bold', color: 'white'
            }}>
              🤖 AI VERDICT: {data.decision}
            </div>
          </div>

        </div>
      )}
    </div>
  );
}

export default App;
